using System;
using System.Linq;
using System.IO;
using MET.Core;
class WildG1Program {
 static int checks;
 static void Check(bool b,string text){checks++;if(!b)throw new Exception(text);}
 static void Near(double a,double b,string text)=>Check(Math.Abs(a-b)<.000001,text+" actual="+a+" expected="+b);
 static void Command(string error,string text)=>Check(error=="",text+" "+error);
 static Game Fresh(Catalog c){var g=new Game(c);g.new_game(20261026,0);Command(g.select_block(0),"block");Command(g.choose_origin(g.s["origin_choices"][0].Text),"origin");return g;}
 static string Home(Game g)=>g.playable_ids().First(id=>g.s["projects"][id]["def"].Text=="homestead").Text;
 static void Done(Game g,string id,string node){Command(WildDesign.Start(g,id,node),"start "+node);var before=g.s["projects"][id]["wild_design"]["nodes"][node]["state"].Text;Check(before=="construction","node reserved");for(int i=0;i<200&&g.s["projects"][id]["upgrade_job"].Count>0;i++)Command(Sim.tick(g,.1),"actual simulation tick");Check(g.s["projects"][id]["upgrade_job"].Count==0,"complete through real queue "+node);}
 static void Base(Game g,string id,double housing,double food){var stats=g.c.projects[g.s["projects"][id]["def"]]["stats"].Duplicate(true);WildDesign.ApplyStats(g,g.s["projects"][id],stats);Near(stats["housing"].Double,housing,"current base housing");Near(stats["output.food"].Double,food,"current base food");}
 static Game RouteFixture(Catalog c,out string id){var g=Fresh(c);id=Home(g);Command(WildDesign.Enable(g),"route enable");g.world_effects["wild_housing_levels"]=30;g.s["block"]["construction_capacity"]=1000;g.s["projects"]["municipal"]["inventory"]["material"]=1000;g.s["projects"]["municipal"]["inventory"]["goods"]=100;g.s["projects"]["municipal"]["inventory"]["food"]=1000;return g;}
 static void RouteChecks(Catalog c,string content){
  var h=RouteFixture(c,out var hid);Check(!WildDesign.Quote(h,hid,"housing")["ok"].Bool&&!WildDesign.Quote(h,hid,"production")["ok"].Bool,"ordinary branches cannot skip compound");Done(h,hid,"compound");Done(h,hid,"housing");Check(WildDesign.Quote(h,hid,"apartment")["ok"].Bool&&!WildDesign.Quote(h,hid,"agriculture")["ok"].Bool,"housing bypass reaches apartment only");Done(h,hid,"organization");Check(!WildDesign.Quote(h,hid,"agriculture")["ok"].Bool,"organization does not conduct to agriculture");
  var p=RouteFixture(c,out var pid);Done(p,pid,"compound");Done(p,pid,"production");Check(WildDesign.Quote(p,pid,"agriculture")["ok"].Bool&&!WildDesign.Quote(p,pid,"apartment")["ok"].Bool,"production bypass reaches agriculture only");Done(p,pid,"fusion");Check(!WildDesign.Quote(p,pid,"apartment")["ok"].Bool,"fusion does not conduct to apartment");
  // Isolated node state fixture separates route conduction from the one-job-at-a-time guard.
  var pending=RouteFixture(c,out var qid);Done(pending,qid,"compound");Done(pending,qid,"housing");pending.s["projects"][qid]["wild_design"]["nodes"]["link"]=V.Map("state","construction","dp",3,"ordinal",1);Check(!WildDesign.Quote(pending,qid,"agriculture")["ok"].Bool,"pending link does not conduct");pending.s["projects"][qid]["wild_design"]["nodes"]["link"]["state"]="complete";Check(WildDesign.Quote(pending,qid,"agriculture")["ok"].Bool&&WildDesign.Quote(pending,qid,"apartment")["ok"].Bool,"completed shared link conducts to both endpoints");
  var shared=RouteFixture(c,out var sid);Done(shared,sid,"compound");Done(shared,sid,"housing");Done(shared,sid,"production");Done(shared,sid,"link");Command(WildDesign.Cancel(shared,sid,"housing"),"cancel housing with alternative production route");Check(shared.s["projects"][sid]["wild_design"]["nodes"].Has("link"),"OR route preserves shared link through production");Command(WildDesign.Cancel(shared,sid,"production"),"cancel remaining incoming route");Check(!shared.s["projects"][sid]["wild_design"]["nodes"].Has("link"),"cascade removes link after last route disappears");
  // Redirect one config edge without changing any node IDs or kinds, proving graph authority.
  var custom=new Catalog(content);foreach(var route in custom.wild["routes"])if(route["from"].Text=="organization"&&route["to"].Text=="apartment")route["to"]="agriculture";
  custom.wild["routes"]=V.Arr(custom.wild["routes"].Where(route=>!route["bypass"].Bool).Cast<object>().ToArray());
  var redirected=RouteFixture(custom,out var rid);Done(redirected,rid,"compound");Done(redirected,rid,"housing");Check(!WildDesign.Quote(redirected,rid,"agriculture")["ok"].Bool,"redirected endpoint still needs completed predecessor");Done(redirected,rid,"organization");Check(WildDesign.Quote(redirected,rid,"agriculture")["ok"].Bool&&!WildDesign.Quote(redirected,rid,"apartment")["ok"].Bool,"config endpoint replaces hardcoded slot semantics");Check(WildDesign.Quote(redirected,rid,"agriculture")["routes_in"].Contains("organization")&&!WildDesign.Quote(redirected,rid,"apartment")["routes_in"].Contains("organization"),"quote incoming IDs follow configured routes");Check(WildDesign.View(redirected,rid)["routes"]==custom.wild["routes"],"view exposes detached authoritative routes");
  var cancelled=WildDesign.CancelPreview(redirected,rid,"housing");Check(cancelled["removed"].Contains("organization"),"custom routes also govern cancellation cascade");
 }
 static int Main(string[] args){var c=new Catalog(args.Length>0?args[0]:"content");var g=Fresh(c);string id=Home(g);Check(!WildDesign.Enabled(g),"legacy game remains legacy until enable");var old=g.snapshot();Near(Construction.capacity_breakdown(g)["base"].Double,c.v040["progression"]["construction_capacity"].Double,"legacy construction base retains existing contract");Command(WildDesign.Enable(g),"enable playable");Near(Construction.capacity_breakdown(g)["base"].Double,10,"Wild initial construction breakdown base is10CP per month");Near(g.s["wild"]["stock"]["low_industrial"].Double,2,"opening grant");var enabled=g.snapshot();Command(WildDesign.Enable(g),"idempotent enable");Check(g.snapshot()==enabled,"second enable no mutation");g.s["block"]["construction_capacity"]=13;Command(WildDesign.Enable(g),"enable after construction growth");Near(Construction.capacity_breakdown(g)["base"].Double,13,"repeat enable retains construction growth");Near(WildDesign.View(g,id)["capacity"]["total"].Double,2,"T1 base capacity");Base(g,id,10,10);
  // Query paths never alter RNG, wallets, inventories or live DP.
  var read=g.snapshot();int revision=g.revision;for(int i=0;i<3;i++){WildDesign.View(g,id);WildDesign.Quote(g,id,"compound");WildDesign.Quote(g,id,"unknown");WildDesign.CancelPreview(g,id,"compound");}Check(read==g.snapshot()&&revision==g.revision,"queries read only");
  var before=g.snapshot();Check(WildDesign.Start(g,id,"housing")!="","prerequisite rejected");Check(before==g.snapshot(),"failed command rollback");
  // Plenty of fixture resources and construction throughput; no fixture result is player pacing evidence.
  g.s["projects"]["municipal"]["inventory"]["material"]=1000;g.s["projects"]["municipal"]["inventory"]["food"]=1000;g.s["projects"]["municipal"]["inventory"]["goods"]=100;g.s["block"]["construction_capacity"]=100;
  Command(WildDesign.Start(g,id,"compound"),"start compound");Base(g,id,10,10);Near(WildDesign.View(g,id)["capacity"]["used"].Double,1,"DP reserved at start");var pending=g.snapshot();Check(WildDesign.Cancel(g,id,"compound")!="","unfinished cancellation deferred");Check(pending==g.snapshot(),"pending rejection unchanged");Command(Sim.tick(g,.02),"partial real tick");Check(g.s["projects"][id]["upgrade_job"].Count==0,"compound CP committed");Base(g,id,11,11);
  Done(g,id,"housing");Base(g,id,12,11);Check(!WildDesign.Quote(g,id,"apartment")["ok"].Bool,"progression insufficient DP");
  g.world_effects["wild_housing_levels"]=3;g.refresh_metrics();Near(WildDesign.View(g,id)["capacity"]["total"].Double,8,"technology current authority +2 per level");
  Done(g,id,"apartment");Base(g,id,24,5.5);Check(g.project_name(id)=="公寓","canonical residence uses Wild name");Near(WildDesign.View(g,id)["capacity"]["total"].Double,10,"inherited +2 capacity");Near(WildDesign.View(g,id)["capacity"]["used"].Double,4,"progression permanently occupies2");Check(g.s["wild"]["unlocked_forms"].Contains("residence"),"completion unlocks direct eligibility");Check(!WildDesign.Quote(g,id,"housing")["ok"].Bool,"no new T2 recipes invented");Check(!WildDesign.Quote(g,id,"production")["pricing_known"].Bool,"T2 unopened node quote unknown");Check(WildDesign.Cancel(g,id,"apartment")!="","tier irreversible");
  var cancel=WildDesign.CancelPreview(g,id,"compound");Check(cancel["ok"].Bool&&cancel["removed"].Contains("housing")&&!cancel["removed"].Contains("apartment"),"cascade preserves tier");Command(WildDesign.Cancel(g,id,"compound"),"cancel predecessor");Base(g,id,20,5);Near(WildDesign.View(g,id)["capacity"]["used"].Double,2,"permanent progression DP remains");Near(g.s["wild"]["stock"]["low_industrial"].Double,1,"spent industrial not refunded");
  string error=g.validate_state(g.s);Command(error,"save validates");var restored=new Game(c);var loaded=restored.migrate_state(V.Parse(g.s.ToJson()));Check(loaded["ok"].Bool,"roundtrip load "+loaded.Get("error","").Text);Check(restored.s["projects"][id]["wild_design"]==g.s["projects"][id]["wild_design"],"save/load authoritative design retained");
  // Slot ordinal is shared and cancellation reprices all survivors.
  var slots=Fresh(c);string sid=Home(slots);Command(WildDesign.Enable(slots),"slot enable");slots.world_effects["wild_housing_levels"]=30;slots.s["block"]["construction_capacity"]=1000;slots.s["projects"]["municipal"]["inventory"]["material"]=1000;slots.s["projects"]["municipal"]["inventory"]["goods"]=100;slots.s["projects"]["municipal"]["inventory"]["food"]=1000;
  Done(slots,sid,"compound");Done(slots,sid,"housing");Done(slots,sid,"production");Near(WildDesign.Quote(slots,sid,"organization")["dp"].Double,3,"firstslot 3DP");Done(slots,sid,"organization");Near(WildDesign.Quote(slots,sid,"link")["dp"].Double,9,"secondslot 9DP");Done(slots,sid,"link");Near(WildDesign.Quote(slots,sid,"fusion")["dp"].Double,27,"thirdslot 27DP");Done(slots,sid,"fusion");Near(WildDesign.View(slots,sid)["capacity"]["used"].Double,42,"ordinary3 plus sharedslot39");
  var slotRead=slots.snapshot();var drop=WildDesign.CancelPreview(slots,sid,"organization");Check(slots.snapshot()==slotRead,"cancel preview readonly");Near(drop["refund_dp"].Double,27,"remove first slot reprices remaining 3+9");Command(WildDesign.Cancel(slots,sid,"organization"),"remove first slot");Near(WildDesign.View(slots,sid)["capacity"]["used"].Double,15,"sharedslot repriced12 plus ordinary3");Near(WildDesign.Quote(slots,sid,"link")["dp"].Double,3,"completed slot quote reports repriced occupiedDP");
  // Cross-route entry must traverse a completed link; a direct branch can bypass every unopened slot.
  var cross=Fresh(c);string cid=Home(cross);Command(WildDesign.Enable(cross),"cross enable");cross.world_effects["wild_housing_levels"]=30;cross.s["block"]["construction_capacity"]=1000;cross.s["projects"]["municipal"]["inventory"]["material"]=1000;cross.s["projects"]["municipal"]["inventory"]["goods"]=100;cross.s["projects"]["municipal"]["inventory"]["food"]=1000;Done(cross,cid,"compound");Done(cross,cid,"housing");Check(!WildDesign.Quote(cross,cid,"agriculture")["ok"].Bool,"cross route withoutlink blocked");Check(WildDesign.Quote(cross,cid,"apartment")["ok"].Bool,"direct route bypasses unopened slots");Done(cross,cid,"link");Check(WildDesign.Quote(cross,cid,"agriculture")["ok"].Bool,"completed link opens cross route");Done(cross,cid,"agriculture");Base(cross,cid,6,22);Check(cross.project_name(cid)=="农场","canonical agriculture uses Wild name");
  RouteChecks(c,args.Length>0?args[0]:"content");
  // Terrain remains a separate real source after Wild base/percentage compilation.
  var terrain=Fresh(c);string tid=Home(terrain);Command(WildDesign.Enable(terrain),"terrain enable");terrain.s["cells"][terrain.s["projects"][tid]["tile"]]["traits"]=V.Arr("tile.fertile");var compiled=Rules.compile(terrain);Near(compiled["stats"][tid]["housing"].Double,10,"compiled farm base housing");Near(compiled["stats"][tid]["output.food"].Double,14.5,"fertile multiplier preserved");
  string tile=terrain.s["cells"].Keys.First(k=>terrain.s["cells"][k]["building"].Text==""&&terrain.s["cells"][k]["terrain"].Text!="water");var fresh=terrain.create_building("homestead",tile,"commons");Check(fresh.Has("wild_design"),"new Wild farm automatically enrolled");Near(fresh["job"]["total"].Double,10,"new Wild T1 build10CP");Check(fresh["slots"].Count==0,"no old free slots");Command(terrain.validate_state(terrain.s),"new construction save validates");
  // Construction offers and previews use the same CP authority as the real job.
  var build=Fresh(c);Command(WildDesign.Enable(build),"build quote enable");build.s["block"]["construction_capacity"]=4;build.s["currency"]=1000;build.refresh_metrics();string buildTile=build.s["cells"].Keys.First(k=>build.s["cells"][k]["building"].Text==""&&!build.s["cells"][k]["traits"].Contains("tile.water"));var rngBefore=build.s["rng"].Duplicate(true);
  Command(Draft.open_build(build,V.Arr(buildTile),"homestead"),"open direct farm build");Check(build.s["draft"]["offers"].Count==1&&build.s["draft"]["offers"][0]["wild_direct"].Bool,"single public construction offer");Check(build.s["rng"]==rngBefore,"Wild farm opens without operator RNG");var direct=build.s["draft"]["offers"][0].Duplicate(true);var price=Draft.offer_cost(build,direct);Near(price["cp"].Double,10,"real offer 10CP");Near(price["hours"].Double,price["cp"].Double/Construction.capacity(build),"offer ETA uses actual CP");Near(price["currency"].Double,c.projects["homestead"]["cost"].Double,"existing currency price retained");Near(price["material"].Double,c.projects["homestead"]["material"].Double,"existing material price retained");var noReroll=build.snapshot();Check(Draft.reroll(build)!=""&&noReroll==build.snapshot(),"no paid operator reroll");Command(build.cancel_draft(),"close direct quote");Command(Draft.open_build(build,V.Arr(buildTile),"homestead"),"reopen direct quote");Check(build.s["draft"]["offers"][0]==direct&&build.s["rng"]==rngBefore,"reopen retains deterministic public offer and RNG");
  var previewBefore=build.snapshot();var forecast=new Planning().compare(build,"homestead",buildTile,direct);Check(forecast["ok"].Bool&&build.snapshot()==previewBefore,"real build forecast read only");Near(forecast["construction_quote"]["cp"].Double,price["cp"].Double,"forecast CP agrees with offer");Command(Draft.accept(build,direct["id"].Text),"accept direct farm");string builtId=build.s["cells"][buildTile]["building"].Text;Near(build.s["projects"][builtId]["job"]["total"].Double,price["cp"].Double,"accepted job matches quoted CP");
  string workshopTile=build.s["cells"].Keys.First(k=>build.s["cells"][k]["building"].Text==""&&!build.s["cells"][k]["traits"].Contains("tile.water"));Command(Draft.open_build(build,V.Arr(workshopTile),"workshop"),"other family tender remains");Check(build.s["draft"]["offers"].Count==3,"other family operator tender unchanged");var workshopPrice=Draft.offer_cost(build,build.s["draft"]["offers"][0]);Command(Draft.accept(build,build.s["draft"]["offers"][0]["id"].Text),"build other T1 family");Near(build.s["projects"][build.s["cells"][workshopTile]["building"]]["job"]["total"].Double,workshopPrice["cp"].Double,"other family quote and actual job agree");Near(workshopPrice["cp"].Double,10,"all Wild T1 share base10CP");
  Console.WriteLine("Wild G1 core PASS "+checks+" checks; actual Sim/Construction queue, readonly queries, DP capacity, progression, cancellation, slots, terrain, save/load.");return 0;
 }
}
